#include <iostream>

bool sideEffectCheck(int id, bool result) {
    std::cout << "Check " << id << " evaluated\n";
    return result;
}

int main() {
    int semesterAverage = 88;
    int finalExam = 92;

    // Logical OR: At least one condition met
    if (semesterAverage >= 90 || finalExam >= 90) {
        std::cout << "Student grade is A\n";
    }

    // Short-circuit demonstration for &&
    std::cout << "Testing && short-circuit:\n";
    if (sideEffectCheck(1, false) && sideEffectCheck(2, true)) {
        std::cout << "Both passed\n";
    } else {
        std::cout << "Short-circuited at 1\n";
    }

    // Short-circuit demonstration for ||
    std::cout << "Testing || short-circuit:\n";
    if (sideEffectCheck(3, true) || sideEffectCheck(4, false)) {
        std::cout << "Short-circuited at 3\n";
    }

    return 0;
}

#include <iostream>

int main() {
    int payCode = 2;

    std::cout << "Initial payCode: " << payCode << "\n";

    // Proper equality test
    if (payCode == 4) {
        std::cout << "Bonus awarded (payCode == 4)\n";
    } else {
        std::cout << "No bonus (payCode != 4)\n";
    }

    // Yoda condition pattern: Prevents accidental assignment
    // If written as (4 = payCode), compiler would raise an error
    if (4 == payCode) {
        std::cout << "Yoda check: Bonus awarded\n";
    } else {
        std::cout << "Yoda check: No bonus\n";
    }

    // Standalone statement pitfall demo
    int counter = 10;
    counter == 20; // Accidental equality check discarded! counter is still 10
    std::cout << "Counter after 'counter == 20;': " << counter << "\n";

    counter = 20;  // Correct assignment
    std::cout << "Counter after 'counter = 20;': " << counter << "\n";

    return 0;
}
